export const cases=[
{id:'capacity',name:'A · Capacity shortfall',description:'A committed launch competes with a constrained critical resource.',facts:[{id:'F-101',product:'Aster 500',location:'Austin',customer:'Northstar Retail',period:'2026-W42',consensusDemand:12000,constrainedDemand:9200,receipts:9000,consensusRevenue:2400000,constrainedRevenue:1840000,aop:2200000,capacityUtilization:1.18,margin:0.31,commitment:true,promotion:true},{id:'F-102',product:'Aster 500',location:'Austin',customer:'All other',period:'2026-W43',consensusDemand:7000,constrainedDemand:6400,receipts:6200,consensusRevenue:1400000,constrainedRevenue:1280000,aop:1350000,capacityUtilization:1.04,margin:0.28,commitment:false,promotion:false}]},
{id:'financial',name:'B · Financial-plan miss',description:'Feasible supply still falls short of the financial plan; mix choices matter.',facts:[{id:'F-201',product:'Orion Pro',location:'Dresden',customer:'Enterprise segment',period:'2026-W42',consensusDemand:10000,constrainedDemand:9800,receipts:10200,consensusRevenue:3600000,constrainedRevenue:2940000,aop:3400000,capacityUtilization:0.83,margin:0.42,commitment:false,promotion:false},{id:'F-202',product:'Orion Core',location:'Dresden',customer:'Enterprise segment',period:'2026-W42',consensusDemand:15000,constrainedDemand:14500,receipts:14800,consensusRevenue:2250000,constrainedRevenue:2175000,aop:2100000,capacityUtilization:0.79,margin:0.24,commitment:false,promotion:true}]},
{id:'nonconvergence',name:'C · Genuine non-convergence',description:'Customer commitment, margin floor, and capacity cannot all be met.',facts:[{id:'F-301',product:'Nova Launch Kit',location:'Monterrey',customer:'Apex Medical',period:'2026-W44',consensusDemand:5000,constrainedDemand:3100,receipts:3000,consensusRevenue:1750000,constrainedRevenue:1085000,aop:1600000,capacityUtilization:1.27,margin:0.17,commitment:true,promotion:true}]}
];
const agents=['Demand','Supply','Finance','Sales & Marketing'];
export const detectIssues=(facts,threshold=5)=>facts.map(f=>{const revenueDelta=f.consensusRevenue-f.constrainedRevenue;const revenueDeltaPct=f.consensusRevenue?revenueDelta/f.consensusRevenue*100:0;const demandGap=f.consensusDemand-f.constrainedDemand;const overCapacity=f.capacityUtilization>1;const materiality=Math.round(Math.min(100,Math.abs(revenueDeltaPct)*2+(overCapacity?30:0)+(f.commitment?15:0)+(f.margin<.2?12:0)));return{id:`ISS-${f.id}`,fact:f,revenueDelta,revenueDeltaPct,demandGap,overCapacity,materiality}}).filter(i=>Math.abs(i.revenueDeltaPct)>=threshold||i.overCapacity||i.fact.commitment).sort((a,b)=>b.materiality-a.materiality);
function position(issue,agent,round,caseId) {const f=issue.fact;let stance='hold',summary='',tradeoff=''; if(agent==='Demand'){stance=issue.demandGap>0?'revise':'support';summary=`Preserve the demand signal of ${f.consensusDemand.toLocaleString()} units; ${issue.demandGap.toLocaleString()} units are not represented in constrained demand.`;tradeoff='Reducing consensus without order, sell-through, or forecast-error evidence risks suppressing a valid signal.'}
else if(agent==='Supply'){stance=issue.overCapacity?'revise':'support';summary=issue.overCapacity?`Capacity is ${Math.round(f.capacityUtilization*100)}% utilized; constrained demand is the feasible baseline pending a validated alternative.`:'Capacity is below the threshold at '+Math.round(f.capacityUtilization*100)+'%; supply is feasible for the reviewed volume.';tradeoff='Expedite, prebuild, or allocation may recover service but require resource and cost validation.'}
else if(agent==='Finance'){stance=issue.revenueDelta>0?'revise':'support';summary=`Constrained revenue is ${money(f.constrainedRevenue)} against AOP ${money(f.aop)}; scenario delta is ${money(issue.revenueDelta)}.`;tradeoff=`Margin is ${Math.round(f.margin*100)}%; revenue recovery should preserve the margin floor and total cost.`}
else {stance=f.commitment?'escalate':'revise';summary=f.commitment?`Customer commitment flagged for ${f.customer}; service exposure requires owner confirmation.`:`No explicit customer commitment is recorded; mix and promotion timing can be reviewed.`;tradeoff='Protecting one commitment may change allocation, launch timing, or another segment’s service.'}
if(round===2&&caseId==='financial'&&agent==='Finance'){stance='support';summary+=' Mix shift toward the higher-margin Orion Pro is a candidate, subject to customer and availability validation.'}
if(round===2&&caseId==='capacity'&&agent==='Sales & Marketing'){stance='hold';summary+=' Retain the committed launch date only if the supply alternative is validated.'}
if(round===2&&caseId==='nonconvergence'&&agent==='Supply')stance='escalate';return{issueId:issue.id,agent,stance,confidence:caseId==='nonconvergence'?.72:.84,evidenceRefs:[f.id,`METRIC-${f.id}-REV`,`METRIC-${f.id}-CAP`],summary,tradeoff,missingData:caseId==='capacity'?['Validated alternate-shift capacity','Expedite cost']:caseId==='nonconvergence'?['Approved margin floor','Customer-approved revised delivery schedule']:[]}}
export function runCase(c,threshold=5){const issues=detectIssues(c.facts,threshold);const round1=issues.flatMap(i=>agents.map(a=>position(i,a,1,c.id)));const round2=issues.flatMap(i=>agents.map(a=>position(i,a,2,c.id)));const decisions=issues.map(i=>{const status=c.id==='nonconvergence'?'human decision required':c.id==='capacity'?'unresolved material conflict':'converged';const proposal=c.id==='financial'?'Review a customer-approved mix shift toward Orion Pro; preserve consensus demand until evidence validates the change.':c.id==='capacity'?'Protect the committed launch as a candidate; validate alternate capacity, expedite cost, and allocation before a decision.':'Escalate commitment versus margin/capacity trade-off to the S&OP owner; do not assert consensus.';return{issueId:i.id,status,proposal,reason:c.id==='financial'?'Functional positions support a conditional mix review; source facts show spare capacity, but customer and availability evidence is still required.':c.id==='capacity'?'Supply feasibility and a flagged commercial commitment remain in conflict; required cost/capacity evidence is missing.':'No option satisfies commitment, 17% margin, and 127% resource utilization simultaneously.'}});return{runId:`SOP-${Date.now().toString(36).toUpperCase()}`,caseId:c.id,createdAt:new Date().toISOString(),issues,round1,round2,decisions,audit:['Synthetic demo data selected; source hash recorded.','Round 0 deterministic issue detection completed before agent run.','Round 1 positions generated independently from common facts.','Round 2 bounded confrontation completed; no free-form agent chat.','Coordinator classified convergence; human decision gates retained.'],approved:false}}
export const money=(n)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
export function validateFacts(value){const errors=[];if(!Array.isArray(value))return{facts:[],errors:['Input must be a CSV array of planning fact rows.']};const required=['product','location','customer','period','consensusDemand','constrainedDemand','receipts','consensusRevenue','constrainedRevenue','aop','capacityUtilization'];const facts=value.map((r,n)=>{required.forEach(k=>{if(r[k]===undefined||r[k]==='')errors.push(`Row ${n+1}: missing ${k}.`)});return{id:String(r.id||`UPLOAD-${n+1}`),product:String(r.product||''),location:String(r.location||''),customer:String(r.customer||''),period:String(r.period||''),consensusDemand:+r.consensusDemand,constrainedDemand:+r.constrainedDemand,receipts:+r.receipts,consensusRevenue:+r.consensusRevenue,constrainedRevenue:+r.constrainedRevenue,aop:+r.aop,capacityUtilization:+r.capacityUtilization,margin:+(r.margin||0),commitment:String(r.commitment||'').toLowerCase()==='true',promotion:String(r.promotion||'').toLowerCase()==='true'}}).filter(f=>Number.isFinite(f.consensusDemand)&&Number.isFinite(f.consensusRevenue));return{facts,errors}}
export function toCSV(issues){return['issue_id,product,location,customer,period,consensus_revenue,constrained_revenue,revenue_delta,capacity_utilization,materiality',...issues.map(i=>[i.id,i.fact.product,i.fact.location,i.fact.customer,i.fact.period,i.fact.consensusRevenue,i.fact.constrainedRevenue,i.revenueDelta,i.fact.capacityUtilization,i.materiality].join(','))].join('\n')}

